/**
 * The GistUI system prompt for the benchmark: generated by @gistui/core from the same 70-component
 * catalog, with the same two worked examples every format gets (the OpenUI ones, written in GistUI's
 * idioms), the same per-group usage notes and the same rules, reworded only where they describe
 * OpenUI's calling convention or array-based data.
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { generatePrompt } from "@gistui/core";
import { benchLibrary } from "./catalog";
import { GUB } from "./gub";
import { ALL_IDIOMS, transcode } from "./transcode";

/** The worked examples from protocols/openui/prompt.ts, read from the pinned checkout. */
export function openuiExamples(): string[] {
  const src = readFileSync(join(GUB, "protocols/openui/prompt.ts"), "utf8");
  const block = /const EXAMPLES = \[([\s\S]*?)\n\];/.exec(src)?.[1] ?? "";
  return [...block.matchAll(/`([\s\S]*?)`/g)].map((m) => m[1]!.replace(/\\`/g, "`"));
}

const RULES = [
  // Same as OpenUI's first rule: format-independent.
  "The root children list is a COMPLETE commitment: every component you define MUST be reachable from root's children, directly or through a listed parent. A defined-but-unreferenced statement renders NOTHING and its content is silently missing from the final screen. Before writing root, enumerate every section you plan to emit; after writing everything, verify every defined variable is reachable from root. The most common mistake is defining a section heading, series or button and never listing it in any children or reference list; every name you define must appear in at least one.",
  // OpenUI's second rule describes its positional convention; this is GistUI's.
  "Required arguments are positional, in the order shown in each signature (or named, `key:value`); every optional argument is named (`key:value`), in any order. Never pass optional arguments positionally and never pad with null. Enum-typed arguments accept ONLY the listed values, exactly as written; never invent variants that are not in the signature.",
  // Same as OpenUI's third rule.
  "Enum lists are closed: a value that is not printed in the signature does not exist, even if other UI libraries use it. Before writing an enum value, check it appears in the signature; if the value you want is missing, use the closest listed value or omit the optional argument.",
  "Each component has its own enum values: Button has variant:primary, but DialogBlock and the other dialogs have no triggerVariant:primary (use default).",
  "Charts and Table take one pipe table as their first argument, `BarChart(sales, xLabel:\"Month\")` with `sales = |Month|Revenue` and its rows. Do not write labels:, values:, Series(…) or Col(…): the table supplies them.",
  "Text arguments are quoted strings, `SectionItem(\"usage\", \"Usage\", …)`; a bare word is a reference to a statement.",
];

/**
 * The catalog's usage notes per component group, exactly as OpenUI's prompt shows them. The few that
 * describe OpenUI's array-based data (Col arrays, labels/Series arrays) are reworded for pipe tables;
 * the check below fails loudly if the pinned bench changes one of them.
 */
const REWORD: Record<string, string> = {
  "- Tabs, Accordion and Steps take item references. Define each item on its own line instead of inlining the whole array.":
    "- Tabs, Accordion and Steps take item references. Define each item on its own line instead of inlining them all in one statement.",
  "- Table is column-oriented: each Col carries the whole data array for its column, so every Col in a table must hold the same number of values.":
    "- A Table takes a pipe table: one row per entry, one cell per column in every row.",
  "- labels holds one entry per position on the category axis; each Series holds one value per label, in the same order.":
    "- A chart takes a pipe table: the first column holds the category-axis positions; each further column is one series, with a value in every row.",
  "- These take two parallel arrays, labels and values in matching order, and show parts of one whole. They cannot show a trend.":
    "- These take a two-column pipe table, label and value, and show parts of one whole. They cannot show a trend.",
  "- Define EACH FormControl as its own reference. Do NOT inline every control in one array.":
    "- Define EACH FormControl as its own reference. Do NOT inline every control in the Form statement.",
};
const { componentGroups } = (await import(join(GUB, "protocols/openui/catalog.ts"))) as { componentGroups: { name: string; notes: string[] }[] };
for (const k of Object.keys(REWORD)) {
  if (!componentGroups.some((g) => g.notes.includes(k))) throw new Error(`bench note changed; update REWORD: ${k.slice(0, 60)}…`);
}
export const groupNotes: Record<string, string[]> = Object.fromEntries(componentGroups.map((g) => [g.name, g.notes.map((n) => REWORD[n] ?? n)]));

/**
 * `GISTUI_BENCH_STYLE=deep` (experimental, for A/B runs): only root's sections get a statement;
 * everything else is written inline. About 5% fewer output tokens; live runs decide if models
 * stay as accurate with long nested statements.
 */
export const DEEP = process.env.GISTUI_BENCH_STYLE === "deep";
const DEEP_RULE = "Give a statement only to the sections listed in root; write everything inside a section inline, in that section's statement.";

export function systemPrompt(): string {
  const idioms = DEEP ? { ...ALL_IDIOMS, deep: true } : ALL_IDIOMS;
  return generatePrompt(benchLibrary(), { examples: openuiExamples().map((e) => transcode(e, idioms)), rules: DEEP ? [...RULES, DEEP_RULE] : RULES, notes: groupNotes, guide: false }).text;
}

export const userPrompt = (brief: { prompt: string }) => brief.prompt;
